"use client";

import {
  ArrowDownToLine,
  CheckCircle2,
  GitCommitHorizontal,
  Plus,
  Radio,
  Sparkles,
} from "lucide-react";
import { useState } from "react";

import {
  ActivityFeed,
  type ActivityFeedItem,
} from "@/components/matos-ui/activity-feed";
import { Badge } from "@/components/matos-ui/badge";
import { Button } from "@/components/matos-ui/button";
import { MetricCard } from "@/components/matos-ui/metric-card";

const ranges = ["7 days", "30 days", "90 days"] as const;

type Range = (typeof ranges)[number];

const metricsByRange: Record<
  Range,
  {
    revenue: number;
    customers: number;
    conversion: number;
    revenueTrend: number;
    customerTrend: number;
    conversionTrend: number;
    revenueSparkline: number[];
    customerSparkline: number[];
    conversionSparkline: number[];
  }
> = {
  "7 days": {
    revenue: 18420,
    customers: 1284,
    conversion: 7.8,
    revenueTrend: 12.5,
    customerTrend: 8.2,
    conversionTrend: 1.4,
    revenueSparkline: [18, 22, 20, 28, 25, 31, 36],
    customerSparkline: [22, 24, 23, 27, 29, 28, 32],
    conversionSparkline: [16, 18, 17, 21, 20, 23, 25],
  },
  "30 days": {
    revenue: 74290,
    customers: 4938,
    conversion: 7.2,
    revenueTrend: 9.8,
    customerTrend: 6.4,
    conversionTrend: 0.8,
    revenueSparkline: [17, 20, 23, 21, 28, 30, 34],
    customerSparkline: [19, 21, 24, 25, 27, 30, 31],
    conversionSparkline: [18, 19, 18, 20, 22, 21, 23],
  },
  "90 days": {
    revenue: 219860,
    customers: 14218,
    conversion: 6.9,
    revenueTrend: 18.6,
    customerTrend: 14.2,
    conversionTrend: -0.3,
    revenueSparkline: [14, 17, 20, 19, 25, 29, 38],
    customerSparkline: [16, 18, 20, 23, 26, 29, 34],
    conversionSparkline: [24, 23, 22, 23, 21, 22, 21],
  },
};

const activityItems: ActivityFeedItem[] = [
  {
    id: "deployment",
    title: "Production deployment completed",
    description: "Release v2.8.0 is live across all regions.",
    time: "4 min ago",
    badge: "Production",
    checks: "12 checks",
    icon: <CheckCircle2 />,
    tone: "success",
    unread: true,
  },
  {
    id: "customer",
    title: "New enterprise workspace",
    description: "Northstar Labs invited 24 team members.",
    time: "38 min ago",
    badge: "Growth",
    icon: <Sparkles />,
    tone: "violet",
  },
  {
    id: "commit",
    title: "Billing workflow updated",
    description: "Marina merged 6 commits into main.",
    time: "2 h ago",
    actor: { name: "Marina Costa", initials: "MC" },
    icon: <GitCommitHorizontal />,
    tone: "neutral",
  },
  {
    id: "incident",
    title: "API latency returned to normal",
    description: "The elevated p95 latency alert was resolved.",
    time: "5 h ago",
    badge: "Resolved",
    icon: <Radio />,
    tone: "info",
  },
];

export function DashboardOverview01() {
  const [range, setRange] = useState<Range>("7 days");
  const metrics = metricsByRange[range];

  return (
    <div
      data-slot="dashboard-overview-01"
      className="@container/dashboard w-full overflow-hidden rounded-2xl border border-border bg-background text-foreground"
    >
      <div className="mx-auto flex min-h-[34rem] w-full max-w-6xl flex-col gap-5 p-4 @2xl/dashboard:p-6">
        <header className="flex flex-col gap-4 @xl/dashboard:flex-row @xl/dashboard:items-end @xl/dashboard:justify-between">
          <div className="min-w-0">
            <div className="mb-2 flex items-center gap-2">
              <Badge variant="soft" size="sm">
                Overview
              </Badge>
              <span className="text-xs text-muted-foreground">
                Friday, July 24
              </span>
            </div>
            <h1 className="text-balance text-2xl font-semibold tracking-tight @2xl/dashboard:text-3xl">
              Good morning, Marina
            </h1>
            <p className="mt-1.5 text-sm text-muted-foreground">
              Here is what changed across your workspace.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Button
              variant="outline"
              className="h-11 flex-1 @sm/dashboard:h-9 @sm/dashboard:flex-none"
            >
              <ArrowDownToLine aria-hidden="true" />
              Export
            </Button>
            <Button className="h-11 flex-1 @sm/dashboard:h-9 @sm/dashboard:flex-none">
              <Plus aria-hidden="true" />
              New report
            </Button>
          </div>
        </header>

        <fieldset className="flex w-full gap-1 overflow-x-auto rounded-xl border border-border bg-muted/45 p-1 @sm/dashboard:w-fit">
          <legend className="sr-only">Dashboard date range</legend>
          {ranges.map((option) => {
            const active = option === range;

            return (
              <button
                key={option}
                type="button"
                aria-pressed={active}
                onClick={() => setRange(option)}
                className={[
                  "min-h-11 flex-1 shrink-0 rounded-lg px-3 text-xs font-medium outline-none transition-colors @sm/dashboard:min-h-8 @sm/dashboard:flex-none",
                  "focus-visible:ring-2 focus-visible:ring-ring",
                  active
                    ? "border border-border bg-card text-foreground shadow-xs"
                    : "text-muted-foreground hover:text-foreground",
                ].join(" ")}
              >
                {option}
              </button>
            );
          })}
        </fieldset>

        <section
          aria-label="Key metrics"
          className="grid gap-3 @xl/dashboard:grid-cols-3"
        >
          <MetricCard
            key={`revenue-${range}`}
            size={undefined}
            label="Net revenue"
            value={metrics.revenue}
            prefix="$"
            trend={{ value: metrics.revenueTrend, label: "vs prior" }}
            sparkline={metrics.revenueSparkline}
          />
          <MetricCard
            key={`customers-${range}`}
            size={undefined}
            label="Active customers"
            value={metrics.customers}
            trend={{ value: metrics.customerTrend }}
            sparkline={metrics.customerSparkline}
          />
          <MetricCard
            key={`conversion-${range}`}
            size={undefined}
            label="Conversion rate"
            value={metrics.conversion}
            suffix="%"
            decimals={1}
            trend={{ value: metrics.conversionTrend }}
            sparkline={metrics.conversionSparkline}
          />
        </section>

        <section aria-label="Recent workspace activity" className="min-w-0">
          <ActivityFeed
            items={activityItems}
            title="Recent activity"
            description="Updates from your team and connected services."
            showAction
            actionLabel="View all"
            compact
          />
        </section>
      </div>
    </div>
  );
}

"use client";

import {
  Bell,
  Camera,
  CheckCircle2,
  LockKeyhole,
  Mail,
  UserRound,
} from "lucide-react";
import { type FormEvent, useId, useState } from "react";

import { Badge } from "@/components/matos-ui/badge";
import { Button } from "@/components/matos-ui/button";
import { InputField } from "@/components/matos-ui/input";
import { TextareaField } from "@/components/matos-ui/textarea";

type SaveStatus = "idle" | "saving" | "saved";

const navigation = [
  { id: "profile", label: "Profile", icon: UserRound, active: true },
  { id: "notifications", label: "Notifications", icon: Bell, active: false },
  { id: "security", label: "Security", icon: LockKeyhole, active: false },
] as const;

export function ProfileSettings01() {
  const formId = useId();
  const [name, setName] = useState("Marina Costa");
  const [email, setEmail] = useState("marina@acme.com");
  const [role, setRole] = useState("Product designer");
  const [bio, setBio] = useState(
    "Designing calm, thoughtful tools for ambitious teams.",
  );
  const [emailError, setEmailError] = useState<string | null>(null);
  const [status, setStatus] = useState<SaveStatus>("idle");

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!email.includes("@")) {
      setEmailError("Enter a valid email address.");
      return;
    }

    setEmailError(null);
    setStatus("saving");

    window.setTimeout(() => {
      setStatus("saved");
    }, 900);
  }

  function markDirty() {
    if (status === "saved") {
      setStatus("idle");
    }
  }

  const isSaving = status === "saving";

  return (
    <div
      data-slot="profile-settings-01"
      className="@container/settings w-full overflow-hidden rounded-2xl border border-border bg-background text-foreground"
    >
      <div className="mx-auto min-h-[34rem] w-full max-w-5xl p-4 @2xl/settings:p-6">
        <header className="border-border border-b pb-5">
          <Badge variant="soft" size="sm">
            Workspace
          </Badge>
          <h1 className="mt-3 text-2xl font-semibold tracking-tight">
            Account settings
          </h1>
          <p className="mt-1.5 text-sm text-muted-foreground">
            Manage your public profile and account preferences.
          </p>
        </header>

        <div className="grid gap-6 pt-5 @3xl/settings:grid-cols-[12rem_minmax(0,1fr)] @3xl/settings:gap-8">
          <nav
            aria-label="Account settings"
            className="flex gap-1 overflow-x-auto @3xl/settings:flex-col"
          >
            {navigation.map((item) => (
              <button
                key={item.id}
                type="button"
                aria-current={item.active ? "page" : undefined}
                className={[
                  "inline-flex min-h-11 shrink-0 items-center gap-2 rounded-xl px-3 text-sm font-medium outline-none transition-colors",
                  "focus-visible:ring-2 focus-visible:ring-ring",
                  item.active
                    ? "border border-border bg-card text-foreground shadow-xs"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground",
                ].join(" ")}
              >
                <item.icon className="size-4" aria-hidden="true" />
                {item.label}
              </button>
            ))}
          </nav>

          <form
            onSubmit={handleSubmit}
            noValidate
            className="min-w-0 overflow-hidden rounded-2xl border border-border bg-card"
          >
            <div className="border-border border-b p-4 @2xl/settings:p-5">
              <h2 className="text-base font-semibold">Profile details</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                This information appears on your workspace profile.
              </p>
            </div>

            <div className="space-y-5 p-4 @2xl/settings:p-5">
              <section
                aria-labelledby={`${formId}-photo-heading`}
                className="flex flex-col gap-4 @sm/settings:flex-row @sm/settings:items-center"
              >
                <div className="relative w-fit">
                  <span
                    aria-hidden="true"
                    className="grid size-16 place-items-center rounded-2xl bg-primary text-lg font-semibold text-primary-foreground"
                  >
                    MC
                  </span>
                  <span className="absolute -bottom-1 -right-1 grid size-6 place-items-center rounded-full border-2 border-card bg-primary text-primary-foreground">
                    <CheckCircle2 className="size-3.5" />
                  </span>
                </div>
                <div className="min-w-0 flex-1">
                  <h3
                    id={`${formId}-photo-heading`}
                    className="text-sm font-medium"
                  >
                    Profile photo
                  </h3>
                  <p className="mt-1 text-xs leading-5 text-muted-foreground">
                    JPG, PNG or WebP. Maximum file size is 2 MB.
                  </p>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  className="h-11 w-full @sm/settings:h-9 @sm/settings:w-auto"
                >
                  <Camera aria-hidden="true" />
                  Change photo
                </Button>
              </section>

              <div className="grid gap-4 @xl/settings:grid-cols-2">
                <InputField
                  id={`${formId}-name`}
                  label="Full name"
                  autoComplete="name"
                  value={name}
                  onChange={(event) => {
                    setName(event.target.value);
                    markDirty();
                  }}
                  reserveMessageSpace={false}
                  disabled={isSaving}
                />
                <InputField
                  id={`${formId}-role`}
                  label="Role"
                  value={role}
                  onChange={(event) => {
                    setRole(event.target.value);
                    markDirty();
                  }}
                  reserveMessageSpace={false}
                  disabled={isSaving}
                />
              </div>

              <InputField
                id={`${formId}-email`}
                type="email"
                label="Email address"
                autoComplete="email"
                value={email}
                onChange={(event) => {
                  setEmail(event.target.value);
                  setEmailError(null);
                  markDirty();
                }}
                error={emailError ?? undefined}
                trailing={<Mail className="size-4" />}
                reserveMessageSpace={Boolean(emailError)}
                disabled={isSaving}
              />

              <TextareaField
                id={`${formId}-bio`}
                label="Bio"
                value={bio}
                maxLength={160}
                onChange={(event) => {
                  setBio(event.target.value);
                  markDirty();
                }}
                description={`${bio.length}/160 characters`}
                reserveMessageSpace={false}
                disabled={isSaving}
              />
            </div>

            <footer className="flex flex-col gap-3 border-border border-t bg-muted/35 p-4 @sm/settings:flex-row @sm/settings:items-center @sm/settings:justify-between @2xl/settings:px-5">
              <output
                aria-live="polite"
                className="min-h-5 text-xs text-muted-foreground"
              >
                {status === "saved"
                  ? "Your profile changes have been saved."
                  : "Changes are visible to workspace members."}
              </output>
              <div className="flex gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  className="h-11 flex-1 @sm/settings:h-9 @sm/settings:flex-none"
                  disabled={isSaving}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  className="h-11 flex-1 @sm/settings:h-9 @sm/settings:flex-none"
                  loading={isSaving}
                  loadingText="Saving…"
                >
                  Save changes
                </Button>
              </div>
            </footer>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { useState } from "react";
import { twMerge } from "tailwind-merge";

import { Badge } from "@/components/matos-ui/badge";
import { Elevated } from "@/components/matos-ui/elevated";
import type { NavGroup } from "../data";

export type NavSectionProps = {
  group: NavGroup;
  activeId: string;
  onSelect: (id: string) => void;
};

const itemBase =
  "group/nav flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring";

export function NavSection({ group, activeId, onSelect }: NavSectionProps) {
  const shouldReduceMotion = useReducedMotion();
  const [open, setOpen] = useState(true);

  return (
    <div data-slot="nav-section" className="space-y-1">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="flex w-full items-center justify-between gap-2 rounded-md px-2.5 py-1 text-[11px] font-medium uppercase tracking-widest text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
      >
        {group.label}
        <ChevronDown
          className={twMerge(
            "size-3.5 transition-transform duration-200",
            open ? "rotate-0" : "-rotate-90",
          )}
          aria-hidden="true"
        />
      </button>

      <AnimatePresence initial={false}>
        {open ? (
          <motion.ul
            key="items"
            initial={
              shouldReduceMotion ? { opacity: 1 } : { height: 0, opacity: 0 }
            }
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { height: "auto", opacity: 1 }
            }
            exit={
              shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
            }
            transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
            className="space-y-0.5 overflow-hidden"
          >
            {group.items.map((item) => {
              const Icon = item.icon;
              const active = item.id === activeId;

              const inner = (
                <>
                  <Icon
                    className={twMerge(
                      "size-4 shrink-0 transition-colors",
                      active
                        ? "text-foreground"
                        : "text-muted-foreground group-hover/nav:text-foreground",
                    )}
                    aria-hidden="true"
                  />
                  <span className="min-w-0 flex-1 truncate text-left">
                    {item.label}
                  </span>
                  {item.badge ? (
                    <Badge variant="count" size="xs" aria-hidden="true">
                      {item.badge}
                    </Badge>
                  ) : null}
                </>
              );

              return (
                <li key={item.id}>
                  {active ? (
                    // Active item lifts one step off the sidebar substrate.
                    <Elevated offset={1} shadowLevel={2} className="rounded-lg">
                      <button
                        type="button"
                        aria-current="page"
                        onClick={() => onSelect(item.id)}
                        className={twMerge(itemBase, "text-foreground")}
                      >
                        {inner}
                      </button>
                    </Elevated>
                  ) : (
                    <button
                      type="button"
                      onClick={() => onSelect(item.id)}
                      className={twMerge(
                        itemBase,
                        "text-muted-foreground hover:bg-surface-3 hover:text-foreground",
                      )}
                    >
                      {inner}
                    </button>
                  )}
                </li>
              );
            })}
          </motion.ul>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronsUpDown, LogOut, Settings, UserRound } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { Elevated } from "@/components/matos-ui/elevated";
import { currentUser } from "../data";

const menuItems = [
  { id: "profile", label: "Profile", icon: UserRound },
  { id: "settings", label: "Account settings", icon: Settings },
];

export function UserMenu() {
  const shouldReduceMotion = useReducedMotion();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) {
      return;
    }

    function handlePointerDown(event: PointerEvent) {
      if (rootRef.current && !rootRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    // Move focus into the menu when it opens.
    menuRef.current
      ?.querySelector<HTMLButtonElement>("[role='menuitem']")
      ?.focus();

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open]);

  return (
    <div ref={rootRef} data-slot="user-menu" className="relative">
      <AnimatePresence>
        {open ? (
          <motion.div
            initial={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, y: 6, scale: 0.98 }
            }
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, y: 4, scale: 0.98 }
            }
            transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
            className="absolute bottom-[calc(100%+0.5rem)] left-0 right-0 z-20"
          >
            {/* Popover lifts two steps off the sidebar substrate, with a
                constant popover shadow regardless of nesting depth. */}
            <Elevated
              offset={2}
              shadowLevel={4}
              className="overflow-hidden rounded-xl p-1"
            >
              <div ref={menuRef} role="menu" aria-label="Account">
                {menuItems.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    role="menuitem"
                    onClick={() => setOpen(false)}
                    className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-foreground outline-none transition-colors hover:bg-surface-5 focus-visible:bg-surface-5 focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <item.icon
                      className="size-4 text-muted-foreground"
                      aria-hidden="true"
                    />
                    {item.label}
                  </button>
                ))}
                <div className="my-1 h-px bg-border" />
                <button
                  type="button"
                  role="menuitem"
                  onClick={() => setOpen(false)}
                  className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-destructive outline-none transition-colors hover:bg-destructive/10 focus-visible:bg-destructive/10 focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <LogOut className="size-4" aria-hidden="true" />
                  Sign out
                </button>
              </div>
            </Elevated>
          </motion.div>
        ) : null}
      </AnimatePresence>

      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="flex w-full items-center gap-2.5 rounded-xl bg-surface-1 px-2 py-2 text-left shadow-surface-1 outline-none transition-colors hover:bg-surface-3 focus-visible:ring-2 focus-visible:ring-ring"
      >
        <span
          aria-hidden="true"
          className="grid size-8 shrink-0 place-items-center rounded-lg bg-primary text-xs font-semibold text-primary-foreground"
        >
          {currentUser.initials}
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm font-medium text-foreground">
            {currentUser.name}
          </span>
          <span className="block truncate text-xs text-muted-foreground">
            {currentUser.email}
          </span>
        </span>
        <ChevronsUpDown
          className="size-4 shrink-0 text-muted-foreground"
          aria-hidden="true"
        />
      </button>
    </div>
  );
}

